                for (int i = 0; i < value.PartsCount && i < value.Parts.Length; ++i)
                {
                    {
                        string why = PartRowFixedFiniteBody(value.Parts[i]);
                        if (why != null) return why;
                    }
                }
            }
            return null;
        }

